using System;

namespace StockLens_DataLayer.Entities
{
    public class StockAnnualReport
    {
        public int Id { get; set; }
        public int StockId { get; set; }
        public Stock Stock { get; set; } = null!;
        public string Title { get; set; } = string.Empty;
        public string? Year { get; set; }
        public string PdfUrl { get; set; } = string.Empty;
        public string? Source { get; set; }
        
        /// <summary>
        /// JSON-serialized structured insights generated by AI from the annual report.
        /// </summary>
        public string? ExtractedInsightsJson { get; set; }

        /// <summary>
        /// Status of the extraction: "Pending", "Processing", "Completed", "Failed", "NotAvailable".
        /// </summary>
        public string ExtractionStatus { get; set; } = "Pending";

        /// <summary>
        /// Timestamp when AI extraction was completed.
        /// </summary>
        public DateTime? ProcessedAt { get; set; }

        /// <summary>
        /// Schema version to support automated data schema upgrades when fields change.
        /// </summary>
        public int SchemaVersion { get; set; } = 1;

        public DateTime FetchedAt { get; set; } = DateTime.UtcNow;
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;
    }
}
